const $=(s,r=document)=>r.querySelector(s);const apiBase="";let token=localStorage.getItem("fenix_token")||"",me=null,chats=[],active=null,messages=[],ws=null,view="chats";
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const initials=s=>(s||"F").trim().split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase();
const time=s=>{try{return new Date(s).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}catch{return""}};
async function req(path,opt={}){const h={...(opt.body instanceof FormData?{}:{"Content-Type":"application/json"}),...(opt.headers||{})};if(token)h.Authorization=`Bearer ${token}`;const r=await fetch(apiBase+path,{...opt,headers:h});if(r.status===401 && !path.includes("/auth/login") && !path.includes("/auth/register")){token="";me=null;localStorage.removeItem("fenix_token");if(ws)try{ws.close()}catch{};render();throw Error("Сессия истекла. Войдите заново.")}const t=await r.text();let d={};try{d=t?JSON.parse(t):{}}catch{d={detail:t}}if(!r.ok){let detail=d.detail;if(Array.isArray(detail))detail=detail.map(x=>x.msg||x.message||String(x)).join("; ");throw Error(detail||"Ошибка запроса");}return d}
function toast(s){const x=document.createElement("div");x.className="toast";x.textContent=s;document.body.append(x);setTimeout(()=>x.remove(),2800)}
function render(){document.body.classList.toggle("dark",localStorage.getItem("fenix_theme")==="dark");if(!token){renderAuth();return}renderApp()}
function renderAuth(){document.getElementById("app").innerHTML=`<div class="auth"><form class="authbox" id="auth"><div class="logo">F</div><h1>Fenix Messenger</h1><p id="authsub">Войдите в свой аккаунт</p><input id="user" placeholder="Логин" autocomplete="username" required><input id="name" placeholder="Имя" autocomplete="name" style="display:none"><input id="pass" placeholder="Пароль" type="password" autocomplete="current-password" required><button>Войти</button><button type="button" class="switch" id="switch">Нет аккаунта? Зарегистрироваться</button></form></div>`;let reg=false;$("#switch").onclick=()=>{reg=!reg;$("#name").style.display=reg?"block":"none";$("#authsub").textContent=reg?"Создайте аккаунт":"Войдите в свой аккаунт";$("#auth button:not(.switch)").textContent=reg?"Создать аккаунт":"Войти";$("#switch").textContent=reg?"Уже есть аккаунт? Войти":"Нет аккаунта? Зарегистрироваться"};$("#auth").onsubmit=async e=>{e.preventDefault();const button=$("#auth button:not(.switch)");button.disabled=true;button.textContent=reg?"Создание…":"Вход…";try{const username=$("#user").value.trim().toLowerCase(),password=$("#pass").value,display_name=$("#name").value.trim();if(!/^[a-z0-9_]+$/.test(username))throw Error("Логин: только латинские буквы, цифры и _");if(username.length<3)throw Error("Логин: минимум 3 символа");if(password.length<6)throw Error("Пароль: минимум 6 символов");if(reg&&display_name.length<1)throw Error("Введите имя");const body=reg?{username,display_name,password}:{username,password};const d=await req(reg?"/api/auth/register":"/api/auth/login",{method:"POST",body:JSON.stringify(body)});if(!d.access_token)throw Error("Сервер не вернул токен авторизации");token=d.access_token;localStorage.setItem("fenix_token",token);await boot()}catch(x){toast(x.message||"Ошибка авторизации");button.disabled=false;button.textContent=reg?"Создать аккаунт":"Войти"}}}
async function boot(){try{me=await req("/api/auth/me");chats=await req("/api/chats");render()}catch(e){if(token){token="";me=null;localStorage.removeItem("fenix_token");}render();if(e?.message)toast(e.message)}}
function renderApp(){document.getElementById("app").innerHTML=`<div class="shell ${active?"mobile-chat":""}"><aside class="sidebar"><div class="brand"><div class="logo">F</div><b>Fenix Messenger</b><button class="icon" id="profile">⚙</button></div><div class="search"><input id="search" placeholder="Поиск пользователей и сообщений"></div><div class="tabs"><button class="active" data-v="chats">Чаты</button><button data-v="people">Люди</button><button data-v="search">Поиск</button></div><div class="chatlist" id="list"></div></aside><main class="main" id="main"></main></div>`;$("#profile").onclick=profileModal;document.querySelectorAll(".tabs button").forEach(b=>b.onclick=()=>{view=b.dataset.v;document.querySelectorAll(".tabs button").forEach(x=>x.classList.toggle("active",x===b));loadList()});$("#search").oninput=debounce(loadList,300);loadList();renderMain()}
function renderMain(){const main=$("#main");if(!active){main.innerHTML=`<div class="empty"><div><h2>Fenix Messenger</h2><p>Выберите чат слева или найдите пользователя.</p></div></div>`;return}main.innerHTML=`<section class="chat"><header class="header"><button class="icon back" id="back">‹</button><div class="avatar">${initials(active.title)}</div><div class="title"><b>${esc(active.title)}</b><small>${esc(active.kind==="group"?active.description:(active.username?"@"+active.username:"личный чат"))}</small></div><button class="icon" id="refresh">↻</button><button class="icon" id="chatinfo">ⓘ</button></header><div class="messages" id="messages"></div><form class="composer" id="composer"><input id="msg" placeholder="Написать сообщение…" autocomplete="off"><button class="send">Отправить</button></form></section>`;$("#back").onclick=()=>{active=null;render()};$("#refresh").onclick=()=>openChat(active);$("#chatinfo").onclick=()=>chatInfo();$("#composer").onsubmit=sendMessage;loadMessages();connectWS()}
async function loadList(){if(!token)return;const q=$("#search")?.value?.trim()||"";const list=$("#list");try{if(view==="people"){const users=await req("/api/users?q="+encodeURIComponent(q));list.innerHTML=users.map(u=>`<div class="chatrow" data-id="${u.id}"><div class="avatar">${initials(u.display_name)}${u.online?'<i class="dot"></i>':''}</div><div class="chatmeta"><b>${esc(u.display_name)}</b><small>@${esc(u.username)}</small></div></div>`).join("");list.querySelectorAll(".chatrow").forEach(r=>r.onclick=async()=>{const c=await req("/api/chats/private",{method:"POST",body:JSON.stringify({other_user_id:+r.dataset.id})});chats=await req("/api/chats");openChat(c)})}else if(view==="search"){if(!q){list.innerHTML=`<div class="empty">Введите запрос</div>`;return}const ms=await req("/api/search/messages?q="+encodeURIComponent(q));list.innerHTML=ms.map(m=>`<div class="chatrow"><div class="avatar">💬</div><div class="chatmeta"><b>Сообщение #${m.id}</b><small>${esc(m.text||"Медиа")}</small></div></div>`).join("")}else{chats=await req("/api/chats");list.innerHTML=chats.map(c=>`<div class="chatrow ${active?.id===c.id?"active":""}" data-id="${c.id}"><div class="avatar">${initials(c.title)}</div><div class="chatmeta"><div class="top"><b>${esc(c.title)}</b><small>#${c.id}</small></div><small>${esc(c.description||"Начните общение")}</small></div></div>`).join("");list.querySelectorAll(".chatrow").forEach(r=>r.onclick=()=>openChat(chats.find(c=>c.id===+r.dataset.id)))} }catch(e){toast(e.message)}}
async function openChat(c){active=c;renderMain();loadList()}
async function loadMessages(){try{messages=await req(`/api/chats/${active.id}/messages`);drawMessages()}catch(e){toast(e.message)}}
function drawMessages(){const box=$("#messages");if(!box)return;box.innerHTML=messages.map(m=>{const mine=m.sender_id===me.id;return`<div class="msg ${mine?"mine":""} ${m.deleted?"deleted":""}" data-id="${m.id}">${m.deleted?"Сообщение удалено":`${m.text?`<div class="text">${esc(m.text)}</div>`:""}${m.media_url?`<img class="media" src="${esc(m.media_url)}" alt="media">`:""}`}<span class="time">${time(m.created_at)}${m.edited?" · изм.":""}${m.pinned?" · 📌":""}</span></div>`}).join("");box.scrollTop=box.scrollHeight;box.querySelectorAll(".msg.mine:not(.deleted)").forEach(el=>el.ondblclick=()=>editMessage(+el.dataset.id))}
async function sendMessage(e){e.preventDefault();const inp=$("#msg"),text=inp.value.trim();if(!text)return;inp.value="";try{const m=await req(`/api/chats/${active.id}/messages`,{method:"POST",body:JSON.stringify({text})});if(!messages.some(x=>x.id===m.id))messages.push(m);drawMessages()}catch(e){toast(e.message)}}
async function editMessage(id){const m=messages.find(x=>x.id===id);const text=prompt("Изменить сообщение",m?.text||"");if(text===null||!text.trim())return;try{const n=await req(`/api/chats/${active.id}/messages/${id}`,{method:"PATCH",body:JSON.stringify({text:text.trim()})});messages=messages.map(x=>x.id===id?n:x);drawMessages()}catch(e){toast(e.message)}}
function connectWS(){if(ws)try{ws.close()}catch{};const proto=location.protocol==="https:"?"wss":"ws";ws=new WebSocket(`${proto}://${location.host}/ws/${active.id}?token=${encodeURIComponent(token)}`);ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.type==="message"&&!messages.some(x=>x.id===d.message.id)){messages.push(d.message);drawMessages()}if(d.type==="message_updated"){messages=messages.map(x=>x.id===d.message.id?d.message:x);drawMessages()}if(d.type==="message_deleted"){messages=messages.map(x=>x.id===d.message_id?{...x,deleted:true,text:""}:x);drawMessages()}}}
function profileModal(){document.body.insertAdjacentHTML("beforeend",`<div class="modalback" id="modal"><div class="modal"><h2>Профиль</h2><div class="profilebig"><div class="avatar">${initials(me.display_name)}</div><b>${esc(me.display_name)}</b><p>@${esc(me.username)}</p></div><input id="pname" value="${esc(me.display_name)}" placeholder="Имя"><textarea id="pbio" placeholder="О себе">${esc(me.bio||"")}</textarea><div class="row"><button class="primary" id="save">Сохранить</button><button class="icon" id="close">✕</button></div><div class="card"><label>Тема</label><button class="primary" id="theme">${localStorage.getItem("fenix_theme")==="dark"?"Светлая тема":"Тёмная тема"}</button></div><button class="danger" id="logout">Выйти из аккаунта</button></div></div>`);$("#close").onclick=()=>$("#modal").remove();$("#save").onclick=async()=>{try{me=await req("/api/users/me",{method:"PATCH",body:JSON.stringify({display_name:$("#pname").value,bio:$("#pbio").value})});$("#modal").remove();render()}catch(e){toast(e.message)}};$("#theme").onclick=()=>{localStorage.setItem("fenix_theme",localStorage.getItem("fenix_theme")==="dark"?"light":"dark");render()};$("#logout").onclick=()=>logout(true)}
async function chatInfo(){try{const ms=await req(`/api/chats/${active.id}/members`);document.body.insertAdjacentHTML("beforeend",`<div class="modalback" id="modal"><div class="modal"><h2>${esc(active.title)}</h2><p>${esc(active.description||"")}</p><div class="card"><b>Участники: ${ms.length}</b>${ms.map(u=>`<div class="userpick"><div class="avatar">${initials(u.display_name)}</div><div><b>${esc(u.display_name)}</b><small>@${esc(u.username)}</small></div></div>`).join("")}</div><button class="primary" id="close">Закрыть</button></div></div>`);$("#close").onclick=()=>$("#modal").remove()}catch(e){toast(e.message)}}
function logout(call){if(call)req("/api/auth/logout",{method:"POST"}).catch(()=>{});token="";me=null;active=null;localStorage.removeItem("fenix_token");if(ws)try{ws.close()}catch{};render()}
function debounce(fn,ms){let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms)}}
if(token){boot()}else{render()}
